// HOCK Content Production Agent — Payload Validator
// Validates all required fields from the webhook POST body

const body = $input.first().json.body || $input.first().json;

const requiredFields = [
  'sessionId',
  'studyUnitId',
  'certificationProgram',
  'certificationName',
  'sectionId',
  'taskName',
  'textbookName',
  'phase',
  'userMessage',
  'intent',
  'timestamp'
];

const missing = requiredFields.filter(field => !body[field]);

if (missing.length > 0) {
  return [{
    json: {
      valid: false,
      error: 'Invalid payload',
      missing,
      received: Object.keys(body)
    }
  }];
}

// Validate timestamp format (ISO 8601)
const tsValid = !isNaN(Date.parse(body.timestamp));
if (!tsValid) {
  return [{
    json: {
      valid: false,
      error: 'Invalid payload',
      missing: ['timestamp (must be ISO 8601 format)'],
      received: Object.keys(body)
    }
  }];
}

// Validate certificationProgram is one of known values
const validPrograms = ['CIA', 'CMA', 'CFE', 'CPA'];
if (!validPrograms.includes(body.certificationProgram)) {
  return [{
    json: {
      valid: false,
      error: 'Invalid payload',
      missing: [`certificationProgram must be one of: ${validPrograms.join(', ')}`],
      received: Object.keys(body)
    }
  }];
}

// All valid — pass through normalized payload
return [{
  json: {
    valid: true,
    sessionId: body.sessionId,
    studyUnitId: body.studyUnitId,
    certificationProgram: body.certificationProgram,
    certificationName: body.certificationName,
    sectionId: body.sectionId,
    taskName: body.taskName,
    textbookName: body.textbookName,
    phase: body.phase,
    userMessage: body.userMessage,
    intent: body.intent,
    timestamp: body.timestamp
  }
}];

