// HOCK Content Production Agent — Phase Router Tool
// Validates phase transitions and returns allowed actions per phase

let inputData = {};
try {
  const rawQuery = $input.first()?.json?.query || '{}';
  inputData = typeof rawQuery === 'string' ? JSON.parse(rawQuery) : rawQuery;
} catch (e) {
  return [{ json: { error: 'Invalid input: ' + e.message, usage: 'Provide JSON with currentPhase, userMessage, intent' } }];
}

const { currentPhase, userMessage, intent } = inputData;

const phaseOrder = [
  'Phase 0: Initiation',
  'Phase 1: Textbook',
  'Phase 2: MCQs',
  'Phase 3: Slides',
  'Phase 4: Script',
  'Phase 5: Flashcards',
  'Phase 6: Close-Out'
];

const phaseConfig = {
  'Phase 0: Initiation': {
    allowedActions: ['confirm_prerequisites'],
    allowedIntents: ['USER_CONFIRMATION_YES', 'USER_CONFIRMATION_NO'],
    nextPhase: 'Phase 1: Textbook',
    nextStepLabel: 'Confirm all source materials are uploaded',
    phaseGateRequired: true,
    gateQuestion: 'Are all required source materials uploaded (syllabus, standards, prior content if applicable)?',
    errorIfSkip: 'Must confirm prerequisites in Phase 0 before starting textbook creation'
  },
  'Phase 1: Textbook': {
    allowedActions: ['generate_textbook', 'revise_textbook', 'upload_dropbox_textbook', 'update_monday_textbook', 'transition_to_phase2'],
    allowedIntents: [
      'PROMPT_TEXTBOOK_SECTION', 'PROMPT_EXPAND', 'PROMPT_CONDENSE', 'PROMPT_REWRITE',
      'PROMPT_INSERT_CONTENT', 'PROMPT_FORMAT_ONLY', 'PROMPT_FALLBACK_REVISION',
      'USER_CONFIRMATION_YES', 'USER_CONFIRMATION_NO', 'PHASE_TRANSITION_REQUEST'
    ],
    nextPhase: 'Phase 2: MCQs',
    nextStepLabel: 'Textbook finalized → Dropbox upload → Monday update → Channel transition',
    phaseGateRequired: true,
    gateQuestion: 'Is the textbook finalized and ready for Dropbox upload?',
    errorIfSkip: 'Must complete Phase 1 (textbook) before starting MCQ creation'
  },
  'Phase 2: MCQs': {
    allowedActions: ['generate_mcqs', 'revise_mcqs', 'export_excel', 'upload_dropbox_mcqs', 'update_monday_mcqs'],
    allowedIntents: [
      'PROMPT_MCQ_GENERATION', 'PROMPT_MCQ_REVISION', 'PROMPT_MCQ_FIX_LENGTH',
      'PROMPT_MCQ_DISTRACTORS', 'PROMPT_MCQ_EXPLANATIONS', 'PROMPT_MCQ_REGENERATE',
      'PROMPT_EXCEL_EXPORT', 'USER_CONFIRMATION_YES', 'USER_CONFIRMATION_NO', 'PHASE_TRANSITION_REQUEST'
    ],
    nextPhase: 'Phase 3: Slides',
    nextStepLabel: 'MCQs finalized → Dropbox upload → Monday update',
    phaseGateRequired: true,
    gateQuestion: 'Are MCQs approved and ready to be saved to Dropbox?',
    errorIfSkip: 'Must complete Phase 2 (MCQs) before starting slide creation'
  },
  'Phase 3: Slides': {
    allowedActions: ['generate_slides', 'revise_slides', 'create_gamma', 'export_pptx', 'update_monday_slides'],
    allowedIntents: [
      'PROMPT_SLIDE_OUTLINE', 'PROMPT_SLIDE_REVISION', 'PROMPT_SLIDE_VISUALS',
      'PROMPT_SLIDE_CONDENSE', 'PROMPT_SLIDE_EXPAND', 'PROMPT_SLIDE_FORMAT',
      'PROMPT_SLIDE_NOTES', 'PROMPT_GAMMA_CREATE', 'PROMPT_EXPORT_AND_MONDAY',
      'USER_CONFIRMATION_YES', 'USER_CONFIRMATION_NO', 'PHASE_TRANSITION_REQUEST'
    ],
    nextPhase: 'Phase 4: Script',
    nextStepLabel: 'Slides finalized → Gamma (optional) → Export → Monday update',
    phaseGateRequired: true,
    gateQuestion: 'Should I store these finalized slides and update the Monday task?',
    errorIfSkip: 'Must complete Phase 3 (slides) before starting script creation'
  },
  'Phase 4: Script': {
    allowedActions: ['generate_script', 'revise_script', 'update_monday_script'],
    allowedIntents: [
      'PROMPT_SCRIPT_NARRATION', 'PROMPT_SCRIPT_REVISION', 'PROMPT_SCRIPT_PACING',
      'PROMPT_SCRIPT_CUES', 'PROMPT_SCRIPT_TIE_VISUALS', 'PROMPT_SCRIPT_SHORTEN',
      'USER_CONFIRMATION_YES', 'USER_CONFIRMATION_NO', 'PHASE_TRANSITION_REQUEST'
    ],
    nextPhase: 'Phase 5: Flashcards',
    nextStepLabel: 'Script finalized → Monday update',
    phaseGateRequired: true,
    gateQuestion: 'Script approved. Would you like me to attach this to the Monday task and update the status?',
    errorIfSkip: 'Must complete Phase 4 (script) before flashcards or close-out'
  },
  'Phase 5: Flashcards': {
    allowedActions: ['generate_flashcards', 'revise_flashcards', 'upload_dropbox_flashcards', 'skip_flashcards'],
    allowedIntents: [
      'PROMPT_FLASHCARD_GUIDE', 'USER_CONFIRMATION_YES', 'USER_CONFIRMATION_NO',
      'PHASE_TRANSITION_REQUEST'
    ],
    nextPhase: 'Phase 6: Close-Out',
    nextStepLabel: 'Flashcards optional — proceed or skip to close-out',
    phaseGateRequired: false,
    gateQuestion: 'Would you like to generate flashcards? This is optional — reply YES to proceed or NO to skip to finalization.',
    errorIfSkip: null
  },
  'Phase 6: Close-Out': {
    allowedActions: ['finalize_monday', 'deliver_summary'],
    allowedIntents: ['PROCESS_CLOSEOUT', 'USER_CONFIRMATION_YES', 'USER_CONFIRMATION_NO'],
    nextPhase: null,
    nextStepLabel: 'Finalize Monday task → Deliver completion summary',
    phaseGateRequired: true,
    gateQuestion: 'All phases are complete. Would you like me to close out this process and finalize the Monday task?',
    errorIfSkip: null
  }
};

// Gate-only intents that require explicit YES before any tool call
const gateIntents = ['USER_CONFIRMATION_YES', 'USER_CONFIRMATION_NO'];

// Find current phase index
const currentIndex = phaseOrder.indexOf(currentPhase);

if (currentIndex === -1) {
  return [{ json: {
    error: `Unknown phase: "${currentPhase}". Valid phases: ${phaseOrder.join(', ')}`,
    phaseOrder
  }}];
}

const config = phaseConfig[currentPhase];

// Check if intent is valid for current phase
if (intent && config.allowedIntents && !config.allowedIntents.includes(intent)) {
  // Check if it's a future-phase intent
  const futurePhaseIntents = [
    'PROMPT_MCQ_GENERATION', 'PROMPT_MCQ_REVISION', 'PROMPT_MCQ_FIX_LENGTH',
    'PROMPT_MCQ_DISTRACTORS', 'PROMPT_MCQ_EXPLANATIONS', 'PROMPT_MCQ_REGENERATE',
    'PROMPT_EXCEL_EXPORT'
  ];
  const slideIntents = [
    'PROMPT_SLIDE_OUTLINE', 'PROMPT_SLIDE_REVISION', 'PROMPT_GAMMA_CREATE', 'PROMPT_EXPORT_AND_MONDAY'
  ];
  const scriptIntents = [
    'PROMPT_SCRIPT_NARRATION', 'PROMPT_SCRIPT_REVISION', 'PROMPT_SCRIPT_PACING'
  ];

  if (currentIndex < 2 && futurePhaseIntents.includes(intent)) {
    return [{ json: {
      error: `Phase gate not cleared. Intent "${intent}" belongs to Phase 2 (MCQs) but current phase is ${currentPhase}. Complete current phase first.`,
      currentPhase,
      phaseGateRequired: true
    }}];
  }
  if (currentIndex < 3 && slideIntents.includes(intent)) {
    return [{ json: {
      error: `Phase gate not cleared. Intent "${intent}" belongs to Phase 3 (Slides) but current phase is ${currentPhase}. Complete current phase first.`,
      currentPhase,
      phaseGateRequired: true
    }}];
  }
  if (currentIndex < 4 && scriptIntents.includes(intent)) {
    return [{ json: {
      error: `Phase gate not cleared. Intent "${intent}" belongs to Phase 4 (Script) but current phase is ${currentPhase}. Complete current phase first.`,
      currentPhase,
      phaseGateRequired: true
    }}];
  }
}

// Check advancement — must be USER_CONFIRMATION_YES to advance gate
if (intent === 'PHASE_TRANSITION_REQUEST') {
  if (config.phaseGateRequired) {
    return [{ json: {
      error: 'Phase gate not cleared. User must confirm YES to the gate question before advancing.',
      currentPhase,
      nextPhase: config.nextPhase,
      phaseGateRequired: true,
      gateQuestion: config.gateQuestion
    }}];
  }
}

const nextPhaseIndex = Math.min(currentIndex + 1, phaseOrder.length - 1);

return [{ json: {
  currentPhase,
  currentPhaseIndex: currentIndex,
  allowedActions: config.allowedActions,
  allowedIntents: config.allowedIntents,
  nextStepLabel: config.nextStepLabel,
  nextPhase: config.nextPhase || phaseOrder[nextPhaseIndex],
  nextPhaseIndex,
  phaseGateRequired: config.phaseGateRequired,
  gateQuestion: config.gateQuestion,
  errorIfSkip: config.errorIfSkip || null,
  intentReceived: intent,
  intentAllowed: !intent || (config.allowedIntents && config.allowedIntents.includes(intent))
}}];

// HOCK Content Production Agent — Monday.com Tool
// Board: 18398486903 | ONLY call after explicit user YES

let inputData = {};
try {
  const rawQuery = $input.first()?.json?.query || '{}';
  inputData = typeof rawQuery === 'string' ? JSON.parse(rawQuery) : rawQuery;
} catch (e) {
  return [{ json: { error: 'Invalid input JSON: ' + e.message } }];
}

const {
  action,
  taskName,
  studyUnitId,
  itemId,
  status,
  description,
  personEmail,
  startDate,
  dueDate,
  fileUrl,
  gammaUrl,
  itemName,
  columnValues
} = inputData;

const BOARD_ID = '18398486903';
const API_URL = 'https://api.monday.com/v2';

// Retrieve API token from environment variable
// Set MONDAY_API_TOKEN in n8n Settings → Environment Variables
const apiToken = $env?.MONDAY_API_TOKEN;
if (!apiToken) {
  return [{ json: {
    error: 'MONDAY_API_TOKEN environment variable not configured.',
    setup: 'Go to n8n Settings → Environment Variables → Add MONDAY_API_TOKEN with your Monday.com API token.'
  }}];
}

const headers = {
  'Content-Type': 'application/json',
  'Authorization': apiToken,
  'API-Version': '2024-01'
};

const today = new Date().toISOString().split('T')[0];
const twoDaysOut = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000).toISOString().split('T')[0];

// Helper: execute GraphQL
async function graphql(query) {
  const response = await fetch(API_URL, {
    method: 'POST',
    headers,
    body: JSON.stringify({ query })
  });
  const data = await response.json();
  if (data.errors) {
    throw new Error('Monday.com API error: ' + JSON.stringify(data.errors));
  }
  return data.data;
}

// ── ACTION: searchItem ──────────────────────────────────────────────────
if (action === 'searchItem') {
  if (!taskName && !studyUnitId) {
    return [{ json: { error: 'searchItem requires taskName or studyUnitId' } }];
  }

  // Primary search by task name
  const primaryQuery = `
    query {
      boards(ids: [${BOARD_ID}]) {
        items_page(limit: 20) {
          items {
            id
            name
            url: relative_link
            column_values {
              id
              text
              value
            }
          }
        }
      }
    }
  `;

  let allItems = [];
  try {
    const data = await graphql(primaryQuery);
    allItems = data?.boards?.[0]?.items_page?.items || [];
  } catch (e) {
    return [{ json: { error: 'Failed to search Monday board: ' + e.message } }];
  }

  // Filter by taskName (case-insensitive)
  let matched = taskName
    ? allItems.filter(i => i.name.toLowerCase().includes(taskName.toLowerCase()))
    : [];

  // Fallback: search by studyUnitId in column values
  if (matched.length === 0 && studyUnitId) {
    matched = allItems.filter(item =>
      item.column_values?.some(cv => cv.text?.includes(studyUnitId) || cv.value?.includes(studyUnitId))
    );
  }

  return [{ json: {
    found: matched.length > 0,
    count: matched.length,
    items: matched.map(i => ({
      id: i.id,
      name: i.name,
      url: `https://hock-international-company.monday.com/boards/${BOARD_ID}/pulses/${i.id}`,
      columns: i.column_values
    })),
    searchedFor: { taskName, studyUnitId },
    boardId: BOARD_ID
  }}];
}

// ── ACTION: updateStatus ────────────────────────────────────────────────
if (action === 'updateStatus') {
  if (!itemId || !status) {
    return [{ json: { error: 'updateStatus requires itemId and status' } }];
  }

  const validStatuses = [
    'In Progress',
    'Textbook is Ready for Review',
    'MCQs Ready for Review',
    'Slides Ready for Review',
    'Slide Script Ready for Review',
    'Complete'
  ];

  if (!validStatuses.includes(status)) {
    return [{ json: {
      error: `Invalid status: "${status}". Valid values: ${validStatuses.join(', ')}`,
      validStatuses
    }}];
  }

  const mutation = `
    mutation {
      change_simple_column_value(
        item_id: ${itemId},
        board_id: ${BOARD_ID},
        column_id: "status",
        value: "${status}"
      ) { id }
    }
  `;

  try {
    await graphql(mutation);
    return [{ json: {
      success: true,
      itemId,
      status,
      itemUrl: `https://hock-international-company.monday.com/boards/${BOARD_ID}/pulses/${itemId}`
    }}];
  } catch (e) {
    return [{ json: { error: e.message, itemId, status } }];
  }
}

// ── ACTION: updateColumns ───────────────────────────────────────────────
if (action === 'updateColumns') {
  if (!itemId) {
    return [{ json: { error: 'updateColumns requires itemId' } }];
  }

  const colVals = {};
  if (status) colVals['status'] = { label: status };
  if (personEmail) colVals['person'] = { email: personEmail, name: personEmail.split('@')[0] };
  if (startDate || today) colVals['date4'] = { date: startDate || today };
  if (dueDate || twoDaysOut) colVals['date'] = { date: dueDate || twoDaysOut };
  if (fileUrl) colVals['file'] = { url: fileUrl, text: 'Download File' };
  if (gammaUrl) colVals['link'] = { url: gammaUrl, text: 'Gamma Presentation' };
  if (columnValues) Object.assign(colVals, columnValues);

  const mutation = `
    mutation {
      change_multiple_column_values(
        item_id: ${itemId},
        board_id: ${BOARD_ID},
        column_values: ${JSON.stringify(JSON.stringify(colVals))}
      ) { id name }
    }
  `;

  try {
    const data = await graphql(mutation);
    const updated = data?.change_multiple_column_values;
    return [{ json: {
      success: true,
      itemId,
      itemName: updated?.name,
      columnsUpdated: Object.keys(colVals),
      itemUrl: `https://hock-international-company.monday.com/boards/${BOARD_ID}/pulses/${itemId}`
    }}];
  } catch (e) {
    return [{ json: { error: e.message, itemId, colVals } }];
  }
}

// ── ACTION: appendDescription ───────────────────────────────────────────
if (action === 'appendDescription') {
  if (!itemId || !description) {
    return [{ json: { error: 'appendDescription requires itemId and description' } }];
  }

  // Get current value
  const getQuery = `
    query {
      items(ids: [${itemId}]) {
        column_values(ids: ["long_text"]) {
          value
          text
        }
      }
    }
  `;

  let currentText = '';
  try {
    const getData = await graphql(getQuery);
    const colVal = getData?.items?.[0]?.column_values?.[0];
    if (colVal?.value) {
      try { currentText = JSON.parse(colVal.value)?.text || colVal.text || ''; }
      catch { currentText = colVal.text || ''; }
    }
  } catch (e) {
    // Column may not exist or have different ID — continue with empty
    currentText = '';
  }

  const newText = currentText
    ? `${currentText}\n\n---\n${description}`
    : description;

  const mutation = `
    mutation {
      change_column_value(
        item_id: ${itemId},
        board_id: ${BOARD_ID},
        column_id: "long_text",
        value: ${JSON.stringify(JSON.stringify({ text: newText }))}
      ) { id }
    }
  `;

  try {
    await graphql(mutation);
    return [{ json: {
      success: true,
      itemId,
      appendedText: description,
      fullDescriptionLength: newText.length,
      itemUrl: `https://hock-international-company.monday.com/boards/${BOARD_ID}/pulses/${itemId}`
    }}];
  } catch (e) {
    return [{ json: { error: e.message, itemId } }];
  }
}

// ── ACTION: createItem (ONLY after explicit user YES) ───────────────────
if (action === 'createItem') {
  if (!itemName && !taskName) {
    return [{ json: { error: 'createItem requires itemName or taskName' } }];
  }

  const colVals = columnValues || {};
  if (status) colVals['status'] = { label: status };
  if (personEmail) colVals['person'] = { email: personEmail, name: personEmail.split('@')[0] };
  colVals['date'] = { date: dueDate || twoDaysOut };

  const mutation = `
    mutation {
      create_item(
        board_id: ${BOARD_ID},
        item_name: "${(itemName || taskName).replace(/"/g, '\\"')}",
        column_values: ${JSON.stringify(JSON.stringify(colVals))}
      ) { id name relative_link }
    }
  `;

  try {
    const data = await graphql(mutation);
    const newItem = data?.create_item;
    return [{ json: {
      success: true,
      itemId: newItem?.id,
      itemName: newItem?.name,
      itemUrl: `https://hock-international-company.monday.com/boards/${BOARD_ID}/pulses/${newItem?.id}`,
      boardUrl: `https://hock-international-company.monday.com/boards/${BOARD_ID}`
    }}];
  } catch (e) {
    return [{ json: { error: e.message } }];
  }
}

return [{ json: {
  error: `Unknown action: "${action}"`,
  validActions: ['searchItem', 'updateStatus', 'updateColumns', 'appendDescription', 'createItem'],
  usage: 'Provide action field plus action-specific fields in JSON'
}}];

// HOCK Content Production Agent — Dropbox Tool
// ONLY call after explicit user YES

let inputData = {};
try {
  const rawQuery = $input.first()?.json?.query || '{}';
  inputData = typeof rawQuery === 'string' ? JSON.parse(rawQuery) : rawQuery;
} catch (e) {
  return [{ json: { error: 'Invalid input JSON: ' + e.message } }];
}

const {
  action,
  certificationProgram,
  studyUnitId,
  contentType,
  fileContent,
  fileName,
  folderPath
} = inputData;

// Retrieve access token from environment variable
// Set DROPBOX_ACCESS_TOKEN in n8n Settings → Environment Variables
const accessToken = $env?.DROPBOX_ACCESS_TOKEN;
if (!accessToken) {
  return [{ json: {
    error: 'DROPBOX_ACCESS_TOKEN environment variable not configured.',
    setup: 'Go to n8n Settings → Environment Variables → Add DROPBOX_ACCESS_TOKEN with your Dropbox access token. For OAuth2, refresh the token via your Dropbox app console.'
  }}];
}

const authHeaders = {
  'Authorization': `Bearer ${accessToken}`
};

// File extension mapping
const extMap = {
  textbook: 'md',
  mcqs: 'xlsx',
  slides: 'pdf',
  script: 'md',
  flashcards: 'pdf'
};

const today = new Date().toISOString().split('T')[0];
const ext = extMap[contentType] || 'md';
const basePath = `/Hock International/Content Production/${certificationProgram}/${studyUnitId}/${contentType}`;
const computedFileName = fileName || `${studyUnitId}_${contentType}_${today}.${ext}`;
const fullPath = `${basePath}/${computedFileName}`;

// Helper: create folder (ignores conflict errors)
async function ensureFolder(path) {
  const response = await fetch('https://api.dropboxapi.com/2/files/create_folder_v2', {
    method: 'POST',
    headers: { ...authHeaders, 'Content-Type': 'application/json' },
    body: JSON.stringify({ path, autorename: false })
  });
  const data = await response.json();
  // Ignore folder-already-exists errors
  if (!response.ok && data?.error?.['.tag'] !== 'path') {
    throw new Error('Dropbox folder creation failed: ' + JSON.stringify(data));
  }
  return data?.metadata || { path_display: path };
}

// ── ACTION: createFolder ─────────────────────────────────────────────────
if (action === 'createFolder') {
  const targetPath = folderPath || basePath;
  try {
    const result = await ensureFolder(targetPath);
    return [{ json: {
      success: true,
      path: targetPath,
      metadata: result
    }}];
  } catch (e) {
    return [{ json: { error: e.message, path: targetPath } }];
  }
}

// ── ACTION: uploadFile ───────────────────────────────────────────────────
if (action === 'uploadFile') {
  if (!fileContent) {
    return [{ json: { error: 'uploadFile requires fileContent (string)' } }];
  }
  if (!certificationProgram || !studyUnitId || !contentType) {
    return [{ json: { error: 'uploadFile requires certificationProgram, studyUnitId, and contentType' } }];
  }

  // Ensure folder exists
  try {
    await ensureFolder(basePath);
  } catch (e) {
    return [{ json: { error: 'Could not create Dropbox folder: ' + e.message, path: basePath } }];
  }

  // Upload the file
  const dropboxApiArg = JSON.stringify({
    path: fullPath,
    mode: 'overwrite',
    autorename: false,
    mute: false,
    strict_conflict: false
  });

  const contentBytes = new TextEncoder().encode(
    typeof fileContent === 'string' ? fileContent : JSON.stringify(fileContent)
  );

  let uploadData;
  try {
    const uploadResponse = await fetch('https://content.dropboxapi.com/2/files/upload', {
      method: 'POST',
      headers: {
        ...authHeaders,
        'Content-Type': 'application/octet-stream',
        'Dropbox-API-Arg': dropboxApiArg
      },
      body: contentBytes
    });
    uploadData = await uploadResponse.json();
    if (!uploadResponse.ok) {
      return [{ json: { error: 'Dropbox upload failed', details: uploadData, path: fullPath } }];
    }
  } catch (e) {
    return [{ json: { error: 'Dropbox upload request failed: ' + e.message, path: fullPath } }];
  }

  // Create shared link
  let sharedUrl = null;
  try {
    const linkResponse = await fetch('https://api.dropboxapi.com/2/sharing/create_shared_link_with_settings', {
      method: 'POST',
      headers: { ...authHeaders, 'Content-Type': 'application/json' },
      body: JSON.stringify({ path: fullPath, settings: { requested_visibility: { '.tag': 'public' } } })
    });
    const linkData = await linkResponse.json();
    sharedUrl = linkData?.url
      || linkData?.error?.shared_link_already_exists?.metadata?.url
      || null;
  } catch (e) {
    // Non-fatal — file uploaded, just couldn't get share link
    sharedUrl = null;
  }

  return [{ json: {
    success: true,
    path: fullPath,
    fileName: computedFileName,
    contentType,
    sharedUrl,
    dropboxMetadata: {
      id: uploadData?.id,
      name: uploadData?.name,
      pathDisplay: uploadData?.path_display,
      size: uploadData?.size,
      serverModified: uploadData?.server_modified
    }
  }}];
}

return [{ json: {
  error: `Unknown action: "${action}"`,
  validActions: ['uploadFile', 'createFolder'],
  pathTemplate: '/Hock International/Content Production/{certificationProgram}/{studyUnitId}/{contentType}/{studyUnitId}_{contentType}_{YYYY-MM-DD}.{ext}'
}}];

// HOCK Content Production Agent — Gamma Tool
// Phase 3 ONLY | ONLY call after explicit user YES

let inputData = {};
try {
  const rawQuery = $input.first()?.json?.query || '{}';
  inputData = typeof rawQuery === 'string' ? JSON.parse(rawQuery) : rawQuery;
} catch (e) {
  return [{ json: { error: 'Invalid input JSON: ' + e.message } }];
}

const {
  action,
  title,
  outlineMarkdown,
  presentationId,
  sectionId,
  certificationName
} = inputData;

const HOCK_THEME_URL = 'https://gamma.app/themes/share/0mk4i94ypgimwxi';
const GAMMA_API_BASE = 'https://api.gamma.app/v1';

// Retrieve API key from environment variable
// Set GAMMA_API_KEY in n8n Settings → Environment Variables
const apiKey = $env?.GAMMA_API_KEY;
if (!apiKey) {
  return [{ json: {
    error: 'GAMMA_API_KEY environment variable not configured.',
    setup: 'Go to n8n Settings → Environment Variables → Add GAMMA_API_KEY with your Gamma API key.'
  }}];
}

const headers = {
  'Content-Type': 'application/json',
  'Authorization': `Bearer ${apiKey}`
};

// ── ACTION: createPresentation ───────────────────────────────────────────
if (action === 'createPresentation') {
  if (!outlineMarkdown) {
    return [{ json: { error: 'createPresentation requires outlineMarkdown (Markdown string with slide outline)' } }];
  }

  const presentationTitle = title
    || (certificationName && sectionId ? `${certificationName} — ${sectionId}` : 'HOCK International Presentation');

  let createData;
  try {
    const response = await fetch(`${GAMMA_API_BASE}/presentations`, {
      method: 'POST',
      headers,
      body: JSON.stringify({
        title: presentationTitle,
        markdown: outlineMarkdown,
        theme: HOCK_THEME_URL,
        mode: 'presentation'
      })
    });
    createData = await response.json();
    if (!response.ok) {
      return [{ json: {
        error: 'Gamma API error creating presentation',
        details: createData,
        note: 'Verify GAMMA_API_KEY is valid and the Gamma API endpoint is correct for your account.'
      }}];
    }
  } catch (e) {
    return [{ json: { error: 'Gamma API request failed: ' + e.message } }];
  }

  return [{ json: {
    success: true,
    presentationId: createData?.id,
    presentationUrl: createData?.url || createData?.shareUrl || createData?.publicUrl,
    editUrl: createData?.editUrl || createData?.editorUrl,
    themeApplied: HOCK_THEME_URL,
    title: presentationTitle,
    slideCount: createData?.slideCount || createData?.slides?.length || null,
    warnings: createData?.warnings || [],
    rawResponse: createData
  }}];
}

// ── ACTION: exportPptx ───────────────────────────────────────────────────
if (action === 'exportPptx') {
  if (!presentationId) {
    return [{ json: { error: 'exportPptx requires presentationId (from createPresentation response)' } }];
  }

  let exportData;
  try {
    const response = await fetch(`${GAMMA_API_BASE}/presentations/${presentationId}/export`, {
      method: 'POST',
      headers,
      body: JSON.stringify({ format: 'pptx' })
    });
    exportData = await response.json();
    if (!response.ok) {
      return [{ json: {
        error: 'Gamma API error exporting presentation',
        details: exportData,
        presentationId
      }}];
    }
  } catch (e) {
    return [{ json: { error: 'Gamma export request failed: ' + e.message, presentationId } }];
  }

  return [{ json: {
    success: true,
    presentationId,
    downloadUrl: exportData?.url || exportData?.downloadUrl || exportData?.fileUrl,
    format: 'pptx',
    fileName: exportData?.fileName || `${presentationId}.pptx`,
    expiresAt: exportData?.expiresAt || null,
    rawResponse: exportData
  }}];
}

return [{ json: {
  error: `Unknown action: "${action}"`,
  validActions: ['createPresentation', 'exportPptx'],
  themeUrl: HOCK_THEME_URL
}}];

// HOCK Content Production Agent — Error Handler
// Catches workflow failures and formats user-friendly error messages

const errorData = $input.first().json;

const errorMessage = errorData?.execution?.error?.message
  || errorData?.error?.message
  || 'An unexpected error occurred';

const nodeName = errorData?.execution?.lastNodeExecuted
  || errorData?.nodeName
  || 'Unknown node';

const executionId = errorData?.execution?.id || 'unknown';

// Format user-friendly message
const userMessage = `I encountered an error while processing your request.

**Error:** ${errorMessage}
**Location:** ${nodeName}

Would you like to:
1. Retry the last action
2. Skip this step and continue
3. Contact support with Execution ID: ${executionId}`;

return [{
  json: {
    errorHandled: true,
    userFriendlyMessage: userMessage,
    technicalDetails: {
      errorMessage,
      failedNode: nodeName,
      executionId,
      timestamp: new Date().toISOString(),
      rawError: errorData
    }
  }
}];
